import * as T from './vendor/three/build/three.module.min.js';
import {OrbitControls} from './vendor/three/examples/jsm/controls/OrbitControls.js';
import {GLTFLoader} from './vendor/three/examples/jsm/loaders/GLTFLoader.js';
export function createBuildScene(host,onSelect){
 const renderer=new T.WebGLRenderer({alpha:true,antialias:true,powerPreference:'low-power'});
 renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;host.append(renderer.domElement);
 const canvas=renderer.domElement;canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();host.dispatchEvent(new CustomEvent('scene-failed'))});canvas.tabIndex=0;canvas.setAttribute('role','img');canvas.setAttribute('aria-label','Interactive PC layout. Drag to rotate, pinch or scroll to zoom. Arrow keys pan. Use the view buttons for keyboard rotation.');
 const scene=new T.Scene(),camera=new T.PerspectiveCamera(38,1,.01,20),root=new T.Group();scene.add(root);
 scene.add(new T.HemisphereLight(0xffffff,0x647088,3));const key=new T.DirectionalLight(0xffffff,4);key.position.set(1,2,3);scene.add(key);const rim=new T.DirectionalLight(0xadc7ff,2);rim.position.set(-2,1,-1);scene.add(rim);
 const controls=new OrbitControls(camera,canvas);controls.enableDamping=false;controls.minDistance=.2;controls.maxDistance=3;controls.maxPolarAngle=Math.PI*.94;controls.target.set(0,0,0);controls.listenToKeyEvents(canvas);
 const loader=new GLTFLoader(),cache=new Map(),parts=[];let currentView='angled';let disposed=false,visible=true,raf=0,revision=0,selected='',exploded=false,panel=false,draws=0;
 const layout={fan:[0,0,0],case:[0,0,0],board:[-.055,.025,-.075],cpu:[-.067,.085,-.06],ram:[0,.069,-.048],gpu:[-.035,-.045,0],ssd:[-.06,-.018,-.06],hdd:[.11,-.176,0],psu:[-.13,-.184,0]};
 function draw(){raf=0;if(disposed||!visible||document.hidden)return;renderer.render(scene,camera);draws++;canvas.dataset.renderCount=String(draws);canvas.dataset.triangles=String(renderer.info.render.triangles)}
 function invalidate(){if(!raf&&!disposed&&visible&&!document.hidden)raf=requestAnimationFrame(draw)}
 function resize(){if(!host.clientWidth)return;renderer.setSize(host.clientWidth,host.clientHeight,false);camera.aspect=host.clientWidth/host.clientHeight;camera.updateProjectionMatrix();invalidate()}
 const resizeObserver=new ResizeObserver(resize);resizeObserver.observe(host);const observer=new IntersectionObserver(([e])=>{visible=e.isIntersecting;if(visible)invalidate()});observer.observe(host);
 function visibility(){if(!document.hidden)invalidate()}document.addEventListener('visibilitychange',visibility);controls.addEventListener('change',invalidate);
 function pose(view='angled'){currentView=view;const bounds=new T.Box3().setFromObject(root),size=bounds.isEmpty()?new T.Vector3(.45,.45,.3):bounds.getSize(new T.Vector3()),center=bounds.isEmpty()?new T.Vector3():bounds.getCenter(new T.Vector3());const fit=Math.max(size.y,size.x/Math.max(camera.aspect,.6),size.z/Math.max(camera.aspect,.6)) / (2*Math.tan(camera.fov*Math.PI/360))*1.5;controls.target.copy(center);const dir=new T.Vector3(...(view==='front'?[1,.05,0]:view==='side'?[0,.02,1]:[.75,.35,1])).normalize();camera.position.copy(center).addScaledVector(dir,Math.max(fit,.7));controls.update();invalidate()}
 function apply(){for(const obj of parts){obj.position.copy(obj.userData.base);if(exploded&&obj.userData.slot!=='case'){const slot=obj.userData.slot;obj.position.z+=slot==='board'?.06:slot==='cpu'?.3:slot==='ram'?.24:slot==='gpu'?.3:.16;obj.position.x+=slot==='hdd'?.16:slot==='psu'?-.14:0;}obj.traverse(m=>{if(!m.isMesh)return;if(m.name==='Side_panel'||m.name==='Side panel')m.visible=panel;for(const mat of (Array.isArray(m.material)?m.material:[m.material])){if(mat.emissive){mat.emissive.set(obj.userData.slot===selected?0x193d76:0x000000);mat.emissiveIntensity=.5;}}});}invalidate()}
 async function load(record){const url=record.model;if(!cache.has(url))cache.set(url,loader.loadAsync(url).then(g=>{if(record.status!=='community')return g;const obj=g.scene,wrap=new T.Group();wrap.add(obj);const angle=record.attribution?.orientation||[0,0,0];obj.rotation.set(...angle);obj.updateMatrixWorld(true);const bounds=new T.Box3().setFromObject(wrap),size=bounds.getSize(new T.Vector3()),want=record.dimensionsMm||[300,50,120];if(Math.min(size.x,size.y,size.z)<=0)throw Error('Invalid model dimensions');wrap.scale.set(want[0]/1000/size.x,want[1]/1000/size.y,want[2]/1000/size.z);wrap.updateMatrixWorld(true);const center=new T.Box3().setFromObject(wrap).getCenter(new T.Vector3());obj.position.sub(center.clone().divide(wrap.scale));g.scene=wrap;return g}).catch(e=>{cache.delete(url);throw e}));return(await cache.get(url)).scene}
 function clear(){for(const obj of parts){obj.traverse(m=>{if(m.isMesh)for(const mat of (Array.isArray(m.material)?m.material:[m.material]))mat.dispose()});root.remove(obj)}parts.length=0}
 async function update(entries,{references=false}={}){const rev=++revision,started=performance.now();const chassis=entries.find(e=>e.slot==='case')?.record,caseSize=chassis?.dimensionsMm||[447,469,215],dual=chassis?.physical?.dual;const boardZ=dual?-caseSize[2]/2000+.101:-.075;const settled=await Promise.all(entries.map(async e=>{if(!e.record?.model)return null;try{return{e,template:await load(e.record)}}catch{return{e,error:true}}}));if(disposed||rev!==revision)return{stale:true};clear();const failed=[];for(const loaded of settled){if(!loaded)continue;if(loaded.error){failed.push(loaded.e.name);continue}const {e,template}=loaded;const count=e.slot==='ram'?Math.min(e.modules||1,8):1;for(let i=0;i<count;i++){const obj=template.clone(true);obj.traverse(m=>{if(m.isMesh)m.material=Array.isArray(m.material)?m.material.map(mat=>mat.clone()):m.material.clone()});const base=new T.Vector3(...layout[e.slot]);if(['board','cpu','ram','ssd'].includes(e.slot))base.z+=boardZ+.075;if(dual&&e.slot==='psu')base.set(-.08,-.08,-caseSize[2]/2000+.045);if(e.slot==='gpu'&&e.record.dimensionsMm)base.x=-caseSize[0]/2000+e.record.dimensionsMm[0]/2000+.012;if(e.slot==='fan'){const f=e.placement,n=f.ordinal||0,step=(e.record.physical?.size?.[0]||120)/1000,z=boardZ+.09;switch(f.position){case'top':base.set((n-1)*step,caseSize[1]/2000-.025,z);obj.rotation.x=-Math.PI/2;break;case'bottom':base.set((n-.5)*step,-caseSize[1]/2000+.025,z);obj.rotation.x=Math.PI/2;break;case'front':base.set(caseSize[0]/2000-.025,(n-.5)*step,z);obj.rotation.y=Math.PI/2;break;case'rear':base.set(-caseSize[0]/2000+.025,.08,z);obj.rotation.y=-Math.PI/2;break;default:base.set(.12,(n-.5)*step,boardZ+.012);}if((f.flow==='intake')!==!!e.record.physical?.reverse)obj.rotateY(Math.PI);const arrow=new T.ArrowHelper(new T.Vector3(0,0,(f.flow==='intake'?-1:1)*(((f.flow==='intake')!==!!e.record.physical?.reverse)?-1:1)),new T.Vector3(0,0,.02),.055,f.flow==='intake'?0x45bfa1:0xeea257,.013,.008);obj.add(arrow);}if(e.slot==='ram')base.x+=(e.index*count+i)*.02;if(e.slot==='ssd')base.y-=e.index*.032;if(e.slot==='gpu')base.y-=e.index*.08;if(e.slot==='hdd')base.y+=e.index*.027;if(e.slot==='cpu')base.x+=e.index*.08;obj.userData={slot:e.slot,base,id:e.id};root.add(obj);parts.push(obj)}}apply();pose(currentView);canvas.dataset.modelCount=String(parts.length);canvas.dataset.loadMs=String(Math.round(performance.now()-started));return{failed,rendered:parts.length,loadMs:Math.round(performance.now()-started)}}
 const ray=new T.Raycaster(),pointer=new T.Vector2();let down=null;
 canvas.addEventListener('pointerdown',e=>{down=[e.clientX,e.clientY]});canvas.addEventListener('pointerup',e=>{if(!down||Math.hypot(e.clientX-down[0],e.clientY-down[1])>6)return;const r=canvas.getBoundingClientRect();pointer.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);ray.setFromCamera(pointer,camera);const hit=ray.intersectObjects(parts,true).find(h=>h.object.visible&&!['Side panel','Side_panel'].includes(h.object.name));if(hit){let obj=hit.object;while(obj&&!obj.userData.slot)obj=obj.parent;if(obj)onSelect(obj.userData.slot)}});
 pose();resize();
 return{update,select(slot){selected=slot;apply()},view:pose,explode(value){exploded=value;apply();pose(currentView)},sidePanel(value){panel=value;apply()},quality(value){renderer.setPixelRatio(value?1:Math.min(devicePixelRatio,1.5));resize()},zoom(delta){camera.position.sub(controls.target).multiplyScalar(delta).add(controls.target);controls.update();invalidate()},rotate(direction){const delta=camera.position.clone().sub(controls.target).applyAxisAngle(new T.Vector3(0,1,0),direction*.25);camera.position.copy(controls.target).add(delta);controls.update();invalidate()},dispose(){disposed=true;revision++;cancelAnimationFrame(raf);resizeObserver.disconnect();observer.disconnect();document.removeEventListener('visibilitychange',visibility);controls.dispose();clear();for(const promise of cache.values())promise.then(g=>g.scene.traverse(m=>{if(m.isMesh){m.geometry.dispose();m.material.dispose()}})).catch(()=>{});cache.clear();renderer.dispose();canvas.remove()}};
}
